function monkeyMove(n) {
  if (n <= 16) {
    // Try every choice of directions and look for a shared corner or a swap along a side.
    let count = 0;
    for (let mask = 0; mask < (1 << n); mask++) {
      const target = [];
      for (let i = 0; i < n; i++) target.push((mask >> i) & 1 ? (i + 1) % n : (i + n - 1) % n);
      const crowded = new Set(target).size < n;
      let crossed = false;
      for (let i = 0; i < n; i++) if (target[target[i]] === i) crossed = true;
      if (crowded || crossed) count++;
    }
    return count;
  }
  // Too many choices to list: every choice collides except the two where all monkeys turn the same way.
  // 2^n is built from the most significant bit of n down.
  const MOD = 1000000007n;
  let power = 1n;
  for (const bit of n.toString(2)) {
    power = power * power % MOD;
    if (bit === '1') power = power * 2n % MOD;
  }
  return Number(((power - 2n) % MOD + MOD) % MOD);
}

