function generate(rand, size) {
  if (size === 'small') return [3 + Math.floor(rand() * 14)];
  const shape = rand();
  if (shape < 0.2) return [1000000000];
  if (shape < 0.35) return [500000003];
  if (shape < 0.5) return [1000000000 - Math.floor(rand() * 20)];
  return [3 + Math.floor(rand() * 999999998)];
}
